import java.util.HashSet;
import java.util.Set;

public class DistinctWordsCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(WordScanner impl) {
        try {
            return DistinctWordsChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectWordScanner()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectWordScanner()));
        check("rejects the capitals-are-different bug", false, verdict(new CaseSensitiveScanner()));
        check("rejects the split-on-one-space bug", false, verdict(new SingleSpaceScanner()));
        check("rejects the crash-on-null bug", false, verdict(new CrashOnNullScanner()));
        check("rejects the always-zero stub", false, verdict(new AlwaysZeroScanner()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectWordScanner implements WordScanner {
    public int distinctWords(String sentence) {
        if (sentence == null) {
            return 0;
        }
        String trimmed = sentence.trim();
        if (trimmed.isEmpty()) {
            return 0;
        }
        Set<String> seen = new HashSet<>();
        for (String word : trimmed.split("\\s+")) {
            if (!word.isEmpty()) {
                seen.add(word.toLowerCase());
            }
        }
        return seen.size();
    }
}

class AlsoCorrectWordScanner implements WordScanner {
    public int distinctWords(String sentence) {
        if (sentence == null || sentence.trim().isEmpty()) {
            return 0;
        }
        java.util.List<String> seen = new java.util.ArrayList<>();
        for (String word : sentence.toLowerCase().trim().split("\\s+")) {
            if (!word.isEmpty() && !seen.contains(word)) {
                seen.add(word);
            }
        }
        return seen.size();
    }
}

