/**
 * TASK: Write the checks that decide whether a WordScanner is correct.
 *
 * The WordScanner contract:
 *   distinctWords(sentence) counts how many DIFFERENT words a sentence holds.
 *   Words are separated by any run of whitespace, capitalisation is ignored,
 *   and a null or blank sentence counts as 0.
 *   Examples: distinctWords("the cat The CAT sat") -> 3
 *             distinctWords("one  two") -> 2   (two spaces, still two words)
 *             distinctWords("") -> 0, distinctWords(null) -> 0
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a number, so a crash counts as a failure: wrap your
 * calls in try/catch and return false if anything is thrown.
 *
 * A sentence of single-spaced lowercase words passes almost every broken
 * scanner. Pick inputs that bite: mixed capitals, a doubled space, padding at
 * the ends, the empty string, and null.
 */
interface WordScanner {
    /* Provided -- do not edit. */
    int distinctWords(String sentence);
}

public class DistinctWordsChecker {

    public static boolean isCorrect(WordScanner impl) {
        try {
            if (impl.distinctWords("the cat The CAT sat") != 3) {
                return false;
            }
            if (impl.distinctWords("one  two") != 2) {
                return false;
            }
            if (impl.distinctWords("  padded  words  ") != 2) {
                return false;
            }
            if (impl.distinctWords("solo") != 1) {
                return false;
            }
            if (impl.distinctWords("") != 0) {
                return false;
            }
            if (impl.distinctWords(null) != 0) {
                return false;
            }
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
